// 主人公が選べるスキル (身につけた技) と能力 (生まれつき・後から得た力)。
// 倍率は転生特典 (engine/cheats.ts) より弱めにする: 死因ごとに 0.5〜0.95、危ない技は代償として 1.1〜1.5。
// 世界の条件: 魔法系は magic、異能は powers、銃・機械・電脳は tech、陰陽術は japan、気功・軽功・剣気は cultivation と eastern。
// 根拠は docs/research/02-cheats-and-skills.md の 2・3・10節と 05-classes-magic-guilds.md の 2・5節。
import type { TraitDef } from '../../engine/types';

type Rest = Omit<TraitDef, 'id' | 'kind' | 'name' | 'desc' | 'cost'>;
type Mult = NonNullable<TraitDef['mult']>;

const skill = (id: string, ja: string, en: string, dja: string, den: string, cost: number, rest: Rest = {}): TraitDef =>
  ({ id, kind: 'skill', name: { ja, en }, desc: { ja: dja, en: den }, cost, ...rest });
const ability = (id: string, ja: string, en: string, dja: string, den: string, cost: number, rest: Rest = {}): TraitDef =>
  ({ id, kind: 'ability', name: { ja, en }, desc: { ja: dja, en: den }, cost, ...rest });

// 魔物・暴力・戦争をまとめて下げる (戦う技)
const fight = (x: number): Mult => ({ monster: x, violence: x, war: x });
// 病・疫病・出産をまとめて下げる (癒やす技)
const cure = (x: number): Mult => ({ disease: x, plague: x, childbirth: x });

const FIGHT_JOBS = { soldier: 1.5, mercenary: 1.5, adventurer: 1.5 } as const;
const MODERN: TraitDef['tags'] = ['scifi', 'modern', 'industrial'];
const EAST_CULT: TraitDef['tags'] = ['cultivation', 'eastern'];
const BEASTS: TraitDef['races'] = ['beast_dog', 'beast_cat', 'beast_rabbit', 'beast_fox', 'beast_wolf'];

